const i=$input.first(), j=i.json, b=i.binary||{};
const errors=[], mode=j.Task, ref=String(j['Invoice reference']||'').trim();
const allowed=['Create from XML','Pair XML with existing PDF','Validate existing hybrid PDF'];
if(!allowed.includes(mode)) errors.push('Choose a supported task.');
if(!ref || ref.length>100) errors.push('Enter an invoice reference of 1 to 100 characters.');
const permission=j['PDF replacement permission'];
if(!['Preserve existing PDF','Allow replacement from XML if needed'].includes(permission)) errors.push('Choose a PDF replacement permission.');
const binary={};
for (const [k,v] of Object.entries(b)) {
 const label=k.replace(/[^a-z]/gi,'').toLowerCase();
 const target=label==='invoicexml'?'xml':label==='invoicepdf'?'sourcePdf':null;
 if(!target || binary[target]) {errors.push('Upload at most one XML and one PDF using the labelled fields.');continue;}
 const data=await this.helpers.getBinaryDataBuffer(0,k);
 if(!data.length || data.length>20*1024*1024) errors.push('Each file must be nonempty and at most 20 MB.');
 if(target==='sourcePdf' && !data.subarray(0,1024).toString('latin1').includes('%PDF-')) errors.push('The PDF upload does not appear to be a PDF.');
 if(target==='xml') {
  const s=data.toString('utf8').replace(/^\uFEFF/,'');
  if(!s.trim().startsWith('<') || !s.includes('CrossIndustryInvoice')) errors.push('Upload UTF-8 CII CrossIndustryInvoice XML exported by your invoicing system. UBL XML is not supported by this template.');
  if(/<!DOCTYPE|<!ENTITY/i.test(s)) errors.push('Use XML without DTD or entity declarations.');
 }
 binary[target]={...v,fileName:target==='xml'?'source-invoice.xml':'source-invoice.pdf'};
}
if(mode!=='Validate existing hybrid PDF' && !binary.xml) errors.push('This task needs an Invoice XML file.');
if(mode!=='Create from XML' && !binary.sourcePdf) errors.push('This task needs an Invoice PDF file.');
if(mode==='Create from XML' && binary.sourcePdf) errors.push('Choose Pair XML with existing PDF to use both files, or remove the PDF.');
if(mode==='Validate existing hybrid PDF' && binary.xml) errors.push('Remove the separate XML: validation checks the XML already embedded in the PDF.');
return [{json:{mode,reference:ref,slug:ref.replace(/[^a-z0-9_-]/gi,'_').slice(0,80)||'invoice',regenerate:mode==='Pair XML with existing PDF'&&permission==='Allow replacement from XML if needed',valid:errors.length===0,errors,startedAt:new Date().toISOString()},binary}];

const j=$input.first().json, p=j.errorPayload||{}, step=j.failedStep||'Workflow processing';
const e=p.error&&typeof p.error==='object'?p.error:p;
const d=e.errorDetails?.errorData||p.errorDetails?.errorData||e.errorData||p.errorData||{};
const raw=[typeof p.error==='string'?p.error:'',e.message,e.errorMessage,e.errorDescription,d.error,d.message].filter(Boolean).join(' ');
const findings=Array.isArray(d.findings)?d.findings:[];
const redacted=/free account|DEMO_REDACTED|watermarked or redacted/i.test(raw)||findings.some(f=>f.comparisonReason==='DEMO_REDACTED');
let why='This step could not complete.',next='The workflow owner should inspect this step in the execution, correct the problem, then start a new submission.';
if(/credential.*does not exist|credential.*not found/i.test(raw)){why='The saved credential could not be found by n8n.';next='Reselect an existing pdfRest credential on all four pdfRest nodes, save, and start a fresh submission.';}
else if(redacted){why='pdfRest reported a free-account or redacted response for this request.';next='Check that the selected key, API base URL and account entitlement belong to the same environment. If your account is paid, have your pdfRest administrator investigate the entitlement. This does not prove your subscription is inactive.';}
else if(findings.some(f=>f.status==='MISMATCH')){why='pdfRest reported a PDF/XML mismatch and rejected preservation.';next='Compare the named field in the PDF and XML. If the values agree, the visual matcher may have interpreted a different value; ask the workflow owner to investigate the source files and provider findings. Start a new submission with Allow replacement from XML only if a regenerated visual invoice is acceptable. The workflow will not enable replacement automatically.';}
else if(/no binary field|binary.*not found/i.test(raw)){why='A required file field is missing.';next='Check XML input xml, source PDF input sourcePdf, and generated PDF output invoice. Restart from the upload form.';}
else if(/401|403|unauthorized|forbidden/i.test(raw)){why='The service rejected access.';next='Check the selected credential, processing environment and access to this operation.';}
else if(/400|bad request/i.test(raw)){why='pdfRest rejected the request. The node may have retained only a short error message.';next=step==='Pair XML and visual PDF'?'Check that the XML and PDF describe the same invoice. The cause could be a content mismatch or another request issue; the full provider response is needed to distinguish them.':'Check the source file and operation settings. Inspect the full provider response before changing invoice values.';}
else if(/429|rate limit/i.test(raw)){why='The service request limit was reached.';next='Wait before starting a new submission.';}
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Never render raw provider errors, keys, URLs, headers or stack traces in the public form.
const labels={payableAmount:'Amount due for payment',netTotal:'Net total',grandTotal:'Grand total',invoiceDate:'Invoice date'};
const mismatchFields=[...new Set(findings.filter(f=>f.status==='MISMATCH').map(f=>labels[f.field]||'Another invoice field'))];
const codes=findings.map(f=>f.code).filter(c=>typeof c==='string'&&/^[A-Z][A-Z0-9_]{1,63}$/.test(c)).slice(0,10);
let reference='Unknown reference';
try {reference=String($('Check invoice submission').first().json.reference||reference).replace(/[\r\n\t]+/g,' ').slice(0,200);}catch{}
return [{json:{reference,failedStep:step,message:'<p><strong>Invoice: '+esc(reference)+'</strong></p><p><strong>Step: '+esc(step)+'</strong></p><p>'+esc(why)+'</p><p>'+esc(next)+'</p>'+(mismatchFields.length?'<p>Reported mismatch: '+mismatchFields.map(esc).join(', ')+'</p>':'')+(codes.length?'<p>Finding codes: '+codes.map(esc).join(', ')+'</p>':'')+'<p>Nothing was approved or released. This execution will be marked failed.</p>',failureSummary:'Invoice '+reference+' NOT RELEASED — processing failed at '+step+': '+why+(codes.length?' Finding codes: '+codes.join(', '):'')}}];

const r=$input.first().json, s=$('Check invoice submission').first().json;
const findings=Array.isArray(r.findings)?r.findings:[];
const known=['NOT_APPLICABLE','CONFIRMED','UNVERIFIED','FAILED','ERROR','DEMO_REDACTED'];
const complete=['VALID','INVALID'].includes(r.status)&&typeof r.pdfa==='boolean'&&known.includes(r.contentMatchStatus)&&typeof r.inputId==='string'&&typeof r.inputUrl==='string'&&(r.findings===undefined||Array.isArray(r.findings))&&findings.every(f=>f&&typeof f.code==='string'&&typeof f.message==='string'&&['INFO','WARNING','BLOCKING','ERROR'].includes(f.severity));
const blocking=findings.some(f=>['BLOCKING','ERROR'].includes(f.severity));
const eligible=complete&&r.status==='VALID'&&r.pdfa===true&&!blocking&&['CONFIRMED','UNVERIFIED','NOT_APPLICABLE'].includes(r.contentMatchStatus);
const needsComparison=r.contentMatchStatus!=='CONFIRMED';
const explanations={CONFIRMED:'The validator confirmed the PDF and XML content match.',UNVERIFIED:'Technical checks passed, but the validator could not confirm every visual value. Compare the PDF with the invoice data in your source system before approving.',NOT_APPLICABLE:'The validator did not perform a PDF/XML visual comparison. Compare the PDF with your source invoice before approving.',FAILED:'The PDF and XML have a detected mismatch. Correct the source invoice and submit it again.',ERROR:'The content comparison could not complete. Investigate and rerun validation.',DEMO_REDACTED:'Your API plan hides the content-match details. Use a plan that exposes the results and rerun before release.'};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Avoid the URL global, which may be unavailable in a Code sandbox.
const reviewPdfUrl=typeof r.inputUrl==='string'?r.inputUrl.trim():'';
const safeReviewUrl=/^https:\/\/[a-z0-9.-]+(?::\d+)?\/[^\s<>"'\\]*$/i.test(reviewPdfUrl);
const link=safeReviewUrl?'<p><strong><a href="'+esc(reviewPdfUrl)+'" target="_blank" rel="noopener noreferrer">Open invoice PDF for review</a></strong></p><p>If the link does not open, copy this address into a new tab: '+esc(reviewPdfUrl)+'</p>':'<p><strong>The PDF review link is unavailable. Choose Hold for correction and ask the workflow owner for the generated PDF. Do not approve an invoice you cannot inspect.</strong></p>';
const summary=!complete?'The service returned an incomplete or unexpected validation result. This invoice is blocked.':!eligible?'This invoice is blocked from release. Correct the reported issues and submit it again.':'Technical validation passed. Human approval is still required.';
const html='<h2>'+esc(s.reference)+'</h2><p>'+esc(summary)+'</p><p>Validation: '+esc(r.status||'UNKNOWN')+' · PDF/A-3: '+(r.pdfa===true?'Passed':'Not confirmed')+'</p><p>'+esc(explanations[r.contentMatchStatus]||'No reliable content-match result was returned.')+'</p>'+link+(findings.length?'<ul>'+findings.slice(0,40).map(f=>'<li>'+esc(f.severity)+' — '+esc(f.code)+': '+esc(f.message)+(f.field?' (field: '+esc(f.field)+')':'')+'</li>').join('')+'</ul>':'')+'<p>Compare seller, buyer, invoice number, dates, currency, line items, tax, totals and payment details. Approval records your decision; it does not change the validator result.</p>';
return [{json:{...s,validation:r,eligible,needsComparison,reviewHtml:html,summary}}];

const s=$('Interpret validation').first().json, j=$input.first().json;
const reviewer=String(j['Reviewer name']||'').trim();
const approved=s.eligible && reviewer.length>0 && j.Decision==='Approve after comparing PDF with source invoice';
return [{json:{...s,disposition:approved?'APPROVED':'HELD',reviewer:reviewer.slice(0,200),reviewNotes:String(j['Review notes']||'').slice(0,4000),reviewedAt:new Date().toISOString(),humanComparisonAttested:approved}}];

const j=$input.first().json, source=$('Check invoice submission').first();
const binary={};
if(j.mode==='Validate existing hybrid PDF') binary.invoice={...source.binary.sourcePdf,fileName:(j.disposition==='APPROVED'?'':'NOT_RELEASED_')+j.slug+'.pdf'};
else {
 const g=$('Keep generated invoice').first();
 binary.invoice={...g.binary.invoice,fileName:(j.disposition==='APPROVED'?'':'NOT_RELEASED_')+j.slug+'.pdf'};
 binary.xml=source.binary.xml;
 if(source.binary.sourcePdf)binary.original=source.binary.sourcePdf;
}
// Resource URLs are temporary; keep findings but omit download URLs from the saved report.
const {inputUrl,...validation}=j.validation;
const report={workflow:'Create and validate ZUGFeRD and Factur-X e-invoices with pdfRest',reference:j.reference,task:j.mode,disposition:j.disposition,startedAt:j.startedAt,completedAt:new Date().toISOString(),replacementAllowed:j.regenerate,reviewer:j.reviewer,reviewedAt:j.reviewedAt||null,humanComparisonAttested:j.humanComparisonAttested,reviewNotes:j.reviewNotes,validation};
binary.report=await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(report,null,2)),'validation-and-review.json','application/json');
const findings=Array.isArray(validation.findings)?validation.findings:[];
const decisionSummary=j.disposition==='APPROVED'?'Technical validation passed and human approval was recorded.':j.disposition==='HELD'?'The reviewer held this invoice. It was not approved for release.':'The validation policy blocked this invoice. It was not approved for release.';
const text=['INVOICE '+j.reference,'Disposition: '+j.disposition,decisionSummary,'Validation status: '+(validation.status||'UNKNOWN'),'PDF/XML match: '+(validation.contentMatchStatus||'UNKNOWN'),'Reviewer: '+(j.reviewer||'Not approved'),'Review notes: '+(j.reviewNotes||''),'',...(findings.map(f=>f.severity+' | '+f.code+' | '+f.message)),'','APPROVED means the technical release policy passed and the named reviewer attested to comparison. This record does not authenticate the reviewer. No invoice was emailed, paid or submitted to a tax authority.','HELD or BLOCKED files are for investigation only. Correct the source system and resubmit.','The original XML is retained unchanged. PDF replacement permission does not prove that regeneration occurred.'];
binary.readme=await this.helpers.prepareBinaryData(Buffer.from(text.join('\n')),'READ-ME.txt','text/plain');
const clean=x=>String(x??'').replace(/[\r\n\t]+/g,' ').slice(0,1200);
const blockingReasons=findings.filter(f=>['BLOCKING','ERROR'].includes(f.severity)).map(f=>clean(f.code)+': '+clean(f.message));
if(!blockingReasons.length && j.disposition==='BLOCKED') blockingReasons.push(clean(j.summary||('Validation '+(validation.status||'UNKNOWN')+'; PDF/A-3 '+(validation.pdfa===true?'passed':'not confirmed')+'; content comparison '+(validation.contentMatchStatus||'UNKNOWN'))));
const completionTitle=j.disposition==='APPROVED'?'Invoice APPROVED — download invoice and audit record':j.disposition==='HELD'?'Invoice HELD — not released; download review record':'Invoice BLOCKED — not released; download validation report';
const failureSummary='Invoice '+clean(j.reference)+' NOT RELEASED — validation BLOCKED. '+blockingReasons.join(' | ')+' See validation-and-review.json for the full report. The API returned a validation result; this is not an API request failure.';
return [{json:{reference:j.reference,disposition:j.disposition,completionTitle,failureSummary,zipName:j.slug+'_'+j.disposition+'.zip'},binary}];

const i=$input.first(), s=$('Check invoice submission').first();
if(typeof i.json.outputId!=='string'||!i.json.outputId||!i.binary?.invoice) throw new Error('The service did not return a completed PDF and resource ID. Check the pdfRest response.');
return [{json:{...s.json,resourceId:i.json.outputId},binary:{...s.binary,invoice:{...i.binary.invoice,fileName:s.json.slug+'.pdf'}}}];
